import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [threatData, setThreatData] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [auditCount, setAuditCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatInput, setChatInput] = useState("");
  const [chatHistory, setChatHistory] = useState([
    { role: 'ai', text: 'Marhaba! I am CyberGuard AI. How can I help?', ar: 'مرحباً! أنا CyberGuard AI. كيف يمكنني مساعدتك؟' }
  ]);
  const chatEndRef = useRef(null);

  // --- IOT LIST WAPAS ADD KIYA ---
  const [iotDevices, setIotDevices] = useState([
    { id: "IOT-RX-01", name: "Riyadh Hub", status: "Online", risk: "Low" },
    { id: "IOT-DXB-02", name: "Dubai Gateway", status: "Online", risk: "Low" },
    { id: "IOT-NEOM-03", name: "NEOM Sensor", status: "Online", risk: "Low" }
  ]);

  // Naya Device Scan Logic
  const discoverNewDevice = () => {
    const regions = ["Riyadh", "Dubai", "Abu Dhabi", "NEOM", "Jeddah"];
    const types = ["Camera", "Power Grid", "Water Sensor", "Traffic Monitor"];
    const newDevice = {
      id: `IOT-${Math.floor(Math.random() * 9000 + 1000)}`,
      name: `${regions[Math.floor(Math.random() * regions.length)]} ${types[Math.floor(Math.random() * types.length)]}`,
      status: "Online", risk: Math.random() > 0.8 ? "Medium" : "Low"
    };
    setIotDevices(prev => [newDevice, ...prev].slice(0, 10));
  };

  const downloadAuditLog = async () => {
    const adminKey = prompt("Enter Admin Secret Key to export logs:");
    if (!adminKey) return;
    try {
      const res = await axios.get(`http://localhost:8000/export-audit?api_key=${adminKey}`);
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(res.data, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `Vision2030_Audit_${Date.now()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
    } catch (err) { alert("❌ Access Denied: Invalid Key!"); }
  };

  const fetchStatus = async () => {
    try {
      // 1. Audit Count Update
      const resCount = await axios.get('http://localhost:8000/audit-status');
      setAuditCount(resCount.data.total_logs);

      // 2. Threat Scanning Logic
      let testPayload = "normal_traffic";
      let testIp = `192.168.1.${Math.floor(Math.random() * 255)}`;
      const randomVal = Math.random();

      if (randomVal > 0.8) {
        testPayload = "UNION SELECT * FROM users--";
        testIp = "HACKER_SQL_INJECT"; 
      } else if (randomVal > 0.6) {
        testIp = "10.0.0." + Math.floor(Math.random() * 100);
      }

      const resAnalyze = await axios.post('http://localhost:8000/analyze-traffic', {
        ip_source: testIp, packet_size: 500, request_count: randomVal > 0.6 ? 900 : 100, payload: testPayload
      });

      setThreatData(resAnalyze.data);
      setLoading(false);

      if (resAnalyze.data.is_anomaly) {
        setAlerts(prev => [{ id: Date.now(), ...resAnalyze.data, time: new Date().toLocaleTimeString() }, ...prev].slice(0, 6));
      }
    } catch (err) { console.error("Backend Offline"); }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const msg = chatInput;
    setChatHistory(prev => [...prev, { role: 'user', text: msg }]);
    setChatInput("");
    try {
      const res = await axios.post('http://localhost:8000/chat', { message: msg });
      setChatHistory(prev => [...prev, { role: 'ai', text: res.data.reply_en, ar: res.data.reply_ar }]);
    } catch (err) { console.error(err); }
  };

  useEffect(() => {
    const tTimer = setInterval(fetchStatus, 5000);
    const dTimer = setInterval(discoverNewDevice, 8000); // Har 8 sec mein naya IoT scan
    return () => { clearInterval(tTimer); clearInterval(dTimer); };
  }, []);

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [chatHistory]);

  return (
    <div style={{ backgroundColor: '#010409', color: '#c9d1d9', minHeight: '100vh', padding: '25px', fontFamily: 'Segoe UI' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #30363d', paddingBottom: '15px', alignItems: 'center' }}>
        <h2 style={{ color: '#58a6ff', margin: 0 }}>🛡️ CyberGuard AI | Vision 2030</h2>
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <span style={{ fontSize: '12px', color: '#8b949e', background: '#161b22', padding: '4px 10px', borderRadius: '15px', border: '1px solid #30363d' }}>📜 {auditCount} Logs Ready</span>
          <button onClick={downloadAuditLog} style={{ background: '#238636', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>📥 Export</button>
        </div>
      </div>

      {/* --- IOT LIST SECTION WAPAS --- */}
      <div style={{ display: 'flex', overflowX: 'auto', gap: '15px', padding: '20px 0' }}>
        {iotDevices.map(d => (
          <div key={d.id} style={{ minWidth: '180px', background: '#0d1117', border: '1px solid #30363d', padding: '15px', borderRadius: '8px', borderLeft: `4px solid ${d.risk === 'Low' ? '#3fb950' : '#f85149'}` }}>
            <div style={{ fontSize: '13px', fontWeight: 'bold' }}>{d.name}</div>
            <div style={{ fontSize: '11px', color: '#8b949e' }}>ID: {d.id} | Risk: {d.risk}</div>
          </div>
        ))}
      </div>

      {/* Analysis Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0', color: '#8b949e' }}>Real-time Analysis</h4>
          {!loading && (
            <div style={{ fontSize: '18px', color: threatData.is_anomaly ? '#f85149' : '#3fb950' }}>
              {threatData.is_anomaly ? '🚨 ANOMALY DETECTED' : '✅ SYSTEM SECURE'}
              <div style={{ fontSize: '12px', color: '#8b949e' }}>Node: {threatData.location}</div>
            </div>
          )}
        </div>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0', color: '#8b949e' }}>Automated Response</h4>
          <div style={{ fontSize: '14px' }}>Action: <strong>{threatData?.recommendation || 'Scanning Network...'}</strong></div>
        </div>
      </div>

      {/* Table */}
      <div style={{ marginTop: '30px', background: '#0d1117', border: '1px solid #30363d', borderRadius: '10px', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ background: '#161b22', color: '#8b949e' }}>
            <tr><th style={{padding:'12px'}}>Time</th><th style={{padding:'12px'}}>Incident</th><th style={{padding:'12px'}}>Origin IP</th><th style={{padding:'12px'}}>Arabic Insight</th></tr>
          </thead>
          <tbody>
            {alerts.map(a => (
              <tr key={a.id} style={{ borderBottom: '1px solid #21262d' }}>
                <td style={{padding:'12px', fontSize:'12px'}}>{a.time}</td>
                <td style={{padding:'12px'}}>{a.analysis_report}</td>
                <td style={{padding:'12px', color:'#58a6ff', fontSize:'12px'}}>{a.ip_source}</td>
                <td style={{padding:'12px', direction:'rtl', color:'#8b949e', fontSize:'13px'}}>{a.arabic_report}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Floating Chatbot */}
      <div style={{ position: 'fixed', bottom: '20px', right: '20px' }}>
        {!isChatOpen ? (
          <button onClick={() => setIsChatOpen(true)} style={{ width: '60px', height: '60px', borderRadius: '50%', background: '#58a6ff', border: 'none', fontSize: '24px', cursor: 'pointer' }}>🤖</button>
        ) : (
          <div style={{ width: '320px', height: '400px', background: '#161b22', border: '1px solid #30363d', borderRadius: '12px', display: 'flex', flexDirection: 'column', boxShadow: '0 8px 24px rgba(0,0,0,0.5)' }}>
            <div style={{ padding: '10px', background: '#0d1117', display: 'flex', justifyContent: 'space-between', borderRadius: '12px 12px 0 0' }}>
              <strong>JAIS AI</strong>
              <button onClick={() => setIsChatOpen(false)} style={{color:'white', background:'none', border:'none', cursor:'pointer'}}>✕</button>
            </div>
            <div style={{ flex: 1, overflowY: 'auto', padding: '10px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {chatHistory.map((m, i) => (
                <div key={i} style={{ alignSelf: m.role === 'user' ? 'flex-end' : 'flex-start', background: m.role === 'user' ? '#1f6feb' : '#30363d', padding: '8px', borderRadius: '8px', fontSize: '12px', maxWidth: '85%' }}>
                  {m.text}
                  {m.ar && <div style={{ borderTop: '1px solid #444', marginTop: '4px', paddingTop: '4px', direction: 'rtl', color: '#8b949e' }}>{m.ar}</div>}
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>
            <div style={{ padding: '10px', display: 'flex' }}>
              <input value={chatInput} onChange={e => setChatInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSendMessage()} style={{ flex: 1, background: '#0d1117', border: '1px solid #30363d', color: 'white', padding: '8px', borderRadius: '4px' }} placeholder="Ask CyberGuard..." />
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
